pub(crate) fn run(
    executable: &Path,
    arguments: &[String],
    environment: &BTreeMap<String, String>,
    input: &[u8],
    limits: SandboxLimits,
) -> Result<SandboxResult> {
    let sid = AppContainerSid::derive(APP_CONTAINER_PROFILE_NAME)?;
    let token = LowBoxToken::create(sid.as_sid())?;
    let mut pipes = StandardPipes::create()?;
    let handles = pipes.child_handles();
    let mut attributes = AttributeList::new(1)?;
    attributes.update(
        PROC_THREAD_ATTRIBUTE_HANDLE_LIST as usize,
        handles.as_ptr() as *const c_void,
        size_of_val(&handles),
    )?;
    let job = Job::create(limits.process_memory_bytes)?;
    let mut process = spawn_suspended(
        executable,
        arguments,
        environment,
        &pipes,
        &mut attributes,
        &token,
    )?;
    let result = execute_suspended(&mut process, &job, &mut pipes, input, limits);
    if result.is_err() {
        process.terminate();
    }
    result
}

