fn install_exact(
    destination: &std::path::Path,
    bytes: &[u8],
    limit: usize,
    label: &str,
) -> Result<()> {
    if destination.exists() {
        if read_artifact(destination, limit, label)? != bytes {
            bail!("foreign-process {label} does not match its artifact CID");
        }
    } else {
        let file_name = destination
            .file_name()
            .and_then(|name| name.to_str())
            .context("foreign-process sandbox artifact name is unavailable")?;
        let temporary = destination.with_file_name(format!(".{file_name}.tmp"));
        let mut file = OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(&temporary)
            .with_context(|| format!("foreign-process {label} could not be staged"))?;
        file.write_all(bytes)?;
        file.sync_all()?;
        drop(file);
        fs::rename(&temporary, &destination)
            .with_context(|| format!("foreign-process {label} could not be installed"))?;
    }
    Ok(())
}

