use std::ffi::OsStr;
use std::path::Path;

use serde_json::Value as JsonValue;
use unicodex_core::{ObjectStore, RefStatus};

use crate::support::{run, run_json};

#[path = "stage_report_chain.rs"]
mod stage_report_chain;
#[path = "stage_report_value.rs"]
mod stage_report_value;

pub(super) use stage_report_chain::{
    assert_legacy_boundary, assert_verified as assert_chain_verified, put_and_assert,
};

use stage_report_value::{ACCEPTED, CHECKED, COMPLETED, FAILED, REJECTED};

pub(super) fn assert_v3_and_legacy(cwd: &Path, stage: &str) -> (String, String) {
    let stage_output = run_json(cwd, stage_verify_command(stage));
    let typed = stage_output["typed_report_cid"]
        .as_str()
        .unwrap()
        .to_owned();
    let store = ObjectStore::open(cwd);
    let value = stage_report_value::report_value(&store, &typed);
    assert_eq!(
        stage_report_value::text(&value, "schema"),
        "unicodex.stage_verification_report.v3"
    );
    stage_report_value::assert_report_counts(&value);
    assert_verified(cwd, &typed, true);

    let forged = stage_report_value::forged_failed_count(&store, &value);
    assert_eq!(store.verify_object(&forged).status, RefStatus::Ok);
    assert_rejected(cwd, &forged, "acceptance summary replay mismatch");

    let v2 =
        stage_report_value::with_schema(&store, &value, "unicodex.stage_verification_report.v2");
    assert_verified(cwd, &v2, true);
    let legacy = stage_report_value::legacy_v1(&store, &value);
    assert_verified(cwd, &legacy, false);
    (typed, legacy)
}

pub(super) fn assert_rejected_before_provision(cwd: &Path, report: &str) {
    let json = rejected_output(cwd, report);
    assert_eq!(json["schema"], "unicodex.stage_verification_report.v3");
    assert_eq!(json["exact_acceptance_summary_replayed"], false);
}

pub(super) fn assert_verified(cwd: &Path, report: &str, exact_summary: bool) {
    let output = run_json(cwd, verify_command(report));
    assert_eq!(output["accepted"], true);
    assert_eq!(output["exact_acceptance_summary_replayed"], exact_summary);
    assert_eq!(output[CHECKED], 1);
    assert_eq!(output[ACCEPTED], 1);
    assert_eq!(output[REJECTED], 0);
    assert_eq!(output[COMPLETED], 0);
    assert_eq!(output[FAILED], 1);
}

fn assert_rejected(cwd: &Path, report: &str, message: &str) {
    let json = rejected_output(cwd, report);
    let actual = json["message"].as_str().unwrap();
    assert!(
        actual.contains(message),
        "expected rejection containing {message:?}, got {actual:?}"
    );
}

fn rejected_output(cwd: &Path, report: &str) -> JsonValue {
    let output = run(cwd, verify_command(report));
    assert_eq!(output.status.code(), Some(2));
    let json = serde_json::from_slice::<JsonValue>(&output.stdout).unwrap();
    assert_eq!(json["accepted"], false);
    json
}

fn stage_verify_command(stage: &str) -> [&OsStr; 5] {
    [
        OsStr::new("stage"),
        OsStr::new("verify"),
        OsStr::new(stage),
        OsStr::new("--format"),
        OsStr::new("json"),
    ]
}

fn verify_command(report: &str) -> [&OsStr; 6] {
    [
        OsStr::new("stage"),
        OsStr::new("report"),
        OsStr::new("verify"),
        OsStr::new(report),
        OsStr::new("--format"),
        OsStr::new("json"),
    ]
}

